[55625] = {id=55625,name="Pearls of Unimaginable Power",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=10052,mapID=1355,description="Thousands of years ago, when the Well of Eternity was destroyed and this land plummeted to the depths of the ocean, a great storm of magical energy was unleashed. Remnants of this magical energy still exist today. Gather the pearls from the ancient mana-infused clams. These enchanted pearls may be powerful weapons in our fight against the naga!",starts={{npcID=152407,x=0.316,y=0.376,mapID=1355}},ends={{npcID=152407,x=0.316,y=0.376,mapID=1355}},coords={x=0.316,y=0.376,source="quest_giver",mapID=1355},questType="world",worldTaskTitle="Pearls of Unimaginable Power",db2QuestInfoID=266,db2QuestInfoName="Combat Ally Quest"},
