[55636] = {id=55636,name="A Life's Work",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=10052,mapID=1355,description="I spent more than one-thousand years researching the mysteries of the arcane before the Great Sundering tore our world apart. I perished amidst the destruction and my work was lost. Search the area for my ancient writings and put my spirit to rest...",starts={{npcID=325853,x=0.785,y=0.287,mapID=1355}},ends={{npcID=325853,x=0.785,y=0.287,mapID=1355}},coords={x=0.785,y=0.287,source="quest_giver",mapID=1355},questType="world",worldTaskTitle="A Life's Work",db2QuestInfoID=266,db2QuestInfoName="Combat Ally Quest"},
