[55683] = {id=55683,name="Forgotten Memories",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=10052,mapID=1355,description="Have we met before? I'm sorry... but I don't remember your name. My name is... Arylina ... I think. My memory has been so foggy since the great explosion happened that sent us underwater. Oh! But look! I can see the sun and the stars again... I wonder what happened? I used to keep a diary, but I can't find it anywhere. If I just had my diary back, I'm sure I could remember more. Will you help me find it?",starts={{npcID=152716,x=0.784,y=0.268,mapID=1355}},ends={{npcID=152716,x=0.784,y=0.268,mapID=1355}},coords={x=0.784,y=0.268,source="quest_giver",mapID=1355},questType="world",worldTaskTitle="Forgotten Memories",db2QuestInfoID=266,db2QuestInfoName="Combat Ally Quest"},
