[56002] = {id=56002,name="Mgglurky's Mugglrgl",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=10052,mapID=1355,description="My cook, Mgglurky, lost his mugglrgl and he's refusing to work until he gets it back. I've got a bar full of hungry murlocs and nothing to feed them until Mgglurky starts cooking. If Mgglurky doesn't find his mugglrgl soon, we're going to have a riot on our hands! I don't know about you, but I definitely don't want to be the main course tonight. There were some Bloodfins lurking around earlier. Search Bloodfin Village for the mugglrgl and bring it back to me once you find it.",starts={{npcID=153884,x=0.254,y=0.264,mapID=1355}},ends={{npcID=153884,x=0.254,y=0.264,mapID=1355}},coords={x=0.254,y=0.264,source="quest_giver",mapID=1355},questType="world",worldTaskTitle="Mgglurky's Mugglrgl",db2QuestInfoID=266,db2QuestInfoName="Combat Ally Quest"},
