[56155] = {id=56155,name="Plug the Geysers",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=10052,mapID=1355,description="The geysers are dangerously unstable and will be erupting any moment now. I fear that Azshara's misuse of the Tidestone is causing irreparable damage to the elements within Nazjatar . We have to do what we can to prevent any further destruction. Take this sealant and use it to stave off the next round of eruptions. In the meantime, I will do what I can to stabilize the elements.",starts={{npcID=154247,x=0.606,y=0.51,mapID=1355}},ends={{npcID=154247,x=0.606,y=0.51,mapID=1355}},coords={x=0.606,y=0.51,source="quest_giver",mapID=1355},questType="world",worldTaskTitle="Plug the Geysers",db2QuestInfoID=266,db2QuestInfoName="Combat Ally Quest"},
[56156] = {id=56156,name="A Tempered Blade",expansion=7,mapID=1355,questType="world",worldTaskTitle="A Tempered Blade"},
[56157] = {id=56157,name="Plug the Geysers",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=10052,mapID=1355,description="There are several geysers nearby that will be erupting soon. Unfortunately, the elements in this area are not stable enough to handle the force of the eruptions. I need someone to plug the geysers while I use the elements to redirect the pressure to a safer area of Nazjatar . Take this sealant and use it to plug the geysers while I work to restore the elemental balance.",starts={{npcID=154246,x=0.31,y=0.378,mapID=1355}},ends={{npcID=154246,x=0.31,y=0.378,mapID=1355}},coords={x=0.31,y=0.378,source="quest_giver",mapID=1355},questType="world",worldTaskTitle="Plug the Geysers",db2QuestInfoID=266,db2QuestInfoName="Combat Ally Quest"},
[56158] = {id=56158,name="Plug the Geysers",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=10052,mapID=1355,description="The elements are becoming increasingly unstable due to Azshara's abuse of the Tidestone. Geysers will be erupting nearby at any moment. Each eruption threatens to destroy the delicate balance of life on the surface. Take this sealant and use it to plug the geysers while I work to restore the elemental balance and redistribute the explosive underground pressure to a safer location.",starts={{npcID=154245,x=0.458,y=0.766,mapID=1355}},ends={{npcID=154245,x=0.458,y=0.766,mapID=1355}},coords={x=0.458,y=0.766,source="quest_giver",mapID=1355},questType="world",worldTaskTitle="Plug the Geysers",db2QuestInfoID=266,db2QuestInfoName="Combat Ally Quest"},
[56159] = {id=56159,name="Plug the Geysers",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=10052,mapID=1355,description="The geysers are dangerously unstable and will be erupting any moment now. I fear that Azshara's misuse of the Tidestone is causing irreparable damage to the elements within Nazjatar . We have to do what we can to prevent any further destruction. Take this sealant and use it to stave off the next round of eruptions. In the meantime, I will do what I can to stabilize the elements.",starts={{npcID=154244,x=0.446,y=0.452,mapID=1355}},ends={{npcID=154244,x=0.446,y=0.452,mapID=1355}},coords={x=0.446,y=0.452,source="quest_giver",mapID=1355},questType="world",worldTaskTitle="Plug the Geysers",db2QuestInfoID=266,db2QuestInfoName="Combat Ally Quest"},
